import React, { useState } from "react";
import { useForm, Controller, SubmitHandler } from "react-hook-form";
import { yupResolver } from "@hookform/resolvers/yup";
import * as yup from "yup";
import { TextField, Button, Box, Typography } from "@mui/material";
import { useTranslation } from "react-i18next";
import { db } from "../../firebaseConfig";
import { collection, addDoc, Timestamp } from "firebase/firestore";
import emailjs from "@emailjs/browser";
import ButtonComponent from "./buttons";

const phoneRegExp = /^\(\d{3}\) \d{3} \d{4}$/;

const schema: yup.ObjectSchema<FormData> = yup.object({
  fullName: yup.string().required("Full name is required"),
  email: yup.string().email("Invalid email").required("Email is required"),
  // phone: yup
  //   .string()
  //   .matches(phoneRegExp, "Phone must be numbers, no spaces or characters")
  //   .required("Phone is required"),
  message: yup.string().required("Message is required"),
}) as yup.ObjectSchema<FormData>;

type FormData = {
  fullName: string;
  email: string;
  // phone: string;
  message: string;
};

export default function ContactForm() {
  const [sending, setSending] = useState(false);
  const [submitted, setSubmitted] = useState(false);
  const { t } = useTranslation();

  const {
    control,
    handleSubmit,
    reset,
    formState: { errors, isValid },
  } = useForm<FormData>({
    resolver: yupResolver(schema),
    mode: "onChange",
    defaultValues: {
      fullName: "",
      email: "",
      // phone: "",
      message: "",
    },
  });

  const onSubmit: SubmitHandler<FormData> = async (data) => {
    setSending(true);
    try {
      await addDoc(collection(db, "contactMessages"), {
        ...data,
        createdAt: Timestamp.now(),
      });

      // const serviceId = process.env.GATSBY_EMAILJS_SERVICE_ID;
      // const templateId = process.env.GATSBY_EMAILJS_TEMPLATE_ID;
      // const publicKey = process.env.GATSBY_EMAILJS_PUBLIC_KEY;

      const serviceId="service_60iafie"
      const templateId="template_34muhgj"
      const publicKey="r2514o3SW3UyPR7Pl"


      if (!serviceId || !templateId || !publicKey) {
        console.error("Missing EmailJS environment variables");
        setSending(false);
        return;
      }

      await emailjs.send(
        serviceId,
        templateId,
        {
          fullName: data.fullName,
          email: data.email,
          // phone: data.phone,
          message: data.message,
        },
        publicKey
      );

      reset();
      setSubmitted(true);
    } catch (error) {
      console.error("Error submitting form:", error);
    } finally {
      setSending(false);
    }
  };

  return (
    <Box
      component="form"
      onSubmit={handleSubmit(onSubmit)}
      className="w-full sm:w-[400px]"
    >
      {submitted ? (
        <Box className="flex flex-col items-center mt-12 p-4 text-center">
          <Typography variant="h6" className="text-LightGrayText body-mob sm:body mb-2">
            {t("contact.form.thankYou") || "Thank you for your message!"}
          </Typography>
          <Typography className="text-LightGrayText body-mob sm:body mb-4">
            {t("contact.form.confirmation") || "We will get back to you shortly."}
          </Typography>
          <Button
            onClick={() => {
              reset();
              setSubmitted(false);
            }}
            className="w-full border 
              !backdrop-blur-md 
              rounded-lg py-4 px-4 body-4
              border-Tofu hover:border-Oatmeal 
              bg-white/10 hover:bg-white/20 
              active:border-DeepSea active:text-DeepSea"
          >
            <span className="text-DarkGreen body-mob sm:body">
              {t("contact.form.backToForm") || "Back to Form"}
            </span>
          </Button>
        </Box>
      ) : (
        <>
          <div className="body-mob sm:body mb-6">
            {t("contact.subtitle")}
          </div>

          {/* Full Name */}
          <Controller
            name="fullName"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                onBlur={(e) => {
                  field.onBlur(); // ejecuta validación
                }}
                label={t("contact.form.name") || "Name"}
                // placeholder="Name"
                error={!!errors.fullName}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-mob sm:body text-LightGrayText"
                InputLabelProps={{ shrink: true }}
                helperText={errors.fullName?.message || ""}
              />
            )}
          />

          {/* Email */}
          <Controller
            name="email"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                label={t("contact.form.email") || "Email"}
                // placeholder="Email"
                error={!!errors.email}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-4 bg-DeepSea/10"
                InputLabelProps={{ shrink: true }}
                helperText={errors.email?.message || ""}
              />
            )}
          />

          {/* Phone */}
          {/* <Controller
            name="phone"
            control={control}
            rules={{
              validate: (value) => {
                const digitsOnly = value.replace(/\D/g, "");
                return (
                  digitsOnly.length === 10 ||
                  t("form.errors.phone") ||
                  "Invalid phone number"
                );
              },
            }}
            render={({ field: { onChange, value, ...field } }) => (
              <TextField
                {...field}
                value={value}
                onChange={(e) => {
                  const digits = e.target.value.replace(/\D/g, "").slice(0, 10);
                  const formatted = digits.replace(
                    /(\d{0,3})(\d{0,3})(\d{0,4})/,
                    (_, p1, p2, p3) =>
                      `${p1 ? `(${p1}` : ""}${p2 ? `) ${p2}` : ""}${p3 ? ` ${p3}` : ""}`
                  );
                  onChange(formatted);
                }}
                label={errors.phone?.message || t("contact.form.phone") || "Phone"}
                placeholder={!errors.phone ? "(123) 456 7890" : ""}
                error={!!errors.phone}
                fullWidth
                margin="dense"
                variant="outlined"
                className="body-4 bg-DeepSea/10"
              />
            )}
          /> */}

          {/* Message */}
          <Controller
            name="message"
            control={control}
            render={({ field }) => (
              <TextField
                {...field}
                value={field.value || " "}
                label={t("contact.form.message") || "Message"}
                // placeholder="Message"
                error={!!errors.message}
                fullWidth
                multiline
                rows={4}
                margin="dense"
                variant="outlined"
                className="body-4 bg-DeepSea/10"
                // InputLabelProps={{ shrink: true }}
                helperText={errors.message?.message || ""}
              />
            )}
          />

          <div className="mt-2">
            <ButtonComponent
              isDisabled={!isValid || sending}
              isSubmit={true}
              sending={sending}
            />
          </div>
        </>
      )}
    </Box>
  );
}
