import React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";

type IntroItem = {
  name: string;
  format: string;
  linkTo: string;
};

type ProductDescription = { item: string };

type Product = {
  id: number;
  name: string;
  subtitle: string;
  format: string;
  image: string;
  description: ProductDescription[];
};

type ProductCategory = {
  category: string;
  product: Product[];
};

const Products: React.FC = () => {
  const { t } = useTranslation();
  const title = t("products.title");
  const paragraph1 = t("products.paragrph1");
  const paragraph2 = t("products.paragrph2");
  const introduction = t("products.introduction", {
    returnObjects: true,
  }) as IntroItem[];

  const items = t("products.items", {
    returnObjects: true,
  }) as ProductCategory[];

  return (
    <section className="relative mt-20" id="products">
          <h2 className="header-mob sm:subheader text-GrayText uppercase mb-8">
            {title}
          </h2>
      <div className="flex  flex-col-reverse sm:flex-row">
        <div className="w-full sm:w-1/3">
          <p className="body-mob sm:body">{paragraph1}</p>
          <p className="body-mob sm:body mt-6 smmt-28">{paragraph2}</p>

          <nav className="flex flex-col gap-12 sm:gap-28 my-12 sm:mt-28">
            {introduction.map((item, index) => (
              <a
                key={index}
                href={item.linkTo}
                className="text-DarkGreen hover:underline"
              >
                <div className="subheader-mob-1 sm:subheader underline sm:no-underline text-DarkGreen uppercase">{item.name}</div>
                <div className="subheader-mob-1 sm:subheader underline sm:no-underline text-DarkGrayText uppercase">{item.format}</div>
              </a>
            ))}
          </nav>

        </div>
        <div className="w-full sm:w-2/3">
          <img className="max-w-[362px] sm:max-w-[1000px] w-full" src={`/products/products.png`} alt="All Products" />
        </div>
      </div>

      {/* Productos */}
      <div className="" >
        {(() => {
          let globalIndex = 0;
          const totalProducts = items.reduce(
            (acc, cur) => acc + cur.product.length,
            0
          );

          return items.map(({ category, product }) =>
            product.map((item) => {
              const isEven = globalIndex % 2 === 0;
              globalIndex++;
              return (
                <React.Fragment key={item.id}>
                <div className="border-t border-DarkGreen/30 w-3/4 sm:w-[60%] mx-auto"></div>
                <div
                  key={item.id}
                  id={category}
                  className={`flex flex-col sm:flex-row items-center gap-10 scroll-mt-4 sm:scroll-mt-0 h-full sm:h-[858px]
                    ${ !isEven ? "sm:flex-row-reverse" : "" }`}
                >
                  <div className="w-full pt-8 sm:hidden block mt-6">
                    <h3 className="header-mob sm:header text-DarkGreen uppercase">
                      {item.name}
                    </h3>
                    {item.subtitle && (
                      <h4 className="header-mob sm:header text-DarkGrayText uppercase">
                        {item.subtitle}
                      </h4>
                    )}
                    <p className="subheader-mob-2 sm:subheader text-DarkGrayText">
                      {item.format}
                    </p>
                  </div>
                  <div className="sm:w-1/2 flex justify-center flex-1">
                    <img
                      src={`/products/${item.image}.png`}
                      alt={item.name}
                      className="object-contain"
                    />
                  </div>
                  <div className="sm:w-1/2 flex flex-col justify-between h-full min-h-full">

                  <div className="flex-1">
                    <h3 className="hidden sm:block header-mob sm:header text-DarkGreen uppercase mt-24">
                      {item.name}
                    </h3>
                    {item.subtitle && (
                      <h4 className="hidden sm:block header-mob sm:header text-DarkGrayText uppercase">
                        {item.subtitle}
                      </h4>
                    )}
                    <p className="hidden sm:block subheader-mob-2 sm:subheader text-DarkGrayText">
                      {item.format}
                    </p>
                  </div>

                  <div className="flex-1 flex items-end">
                    <ul className="list-none body-mob sm:body text-DarkGrayText space-y-4 mb-12 sm:mb-24">
                      {item.description.map((desc, i) => (
                        <li
                          key={i}
                          dangerouslySetInnerHTML={{ __html: desc.item }}
                        />
                      ))}
                    </ul>                    
                  </div>
                  </div>
                </div>
                </React.Fragment>
              );
            })
          );
        })()
        }
      </div>
    </section>
  );
};

export default Products;
